"""Scrive automatico/catalogo.json: le idee pronte per le prossime settimane (battute, regalo e app di ognuna).
Il generatore della settimana (automatico/settimana.py) ne prende tre nuove ogni domenica; quando finiscono, il modello AI
locale ne scrive altre con lo stesso schema (automatico/ai.py) e qui si possono sempre aggiungere a mano.

Campi di un'idea:
  nome, emoji, telefono (scritta corta sul telefono della bancarella), problema (per «X, Y o Z: chi vi frega di più?»),
  storia (battuta del martedì quando l'idea è la A), domandaE (battuta del martedì quando è la B o la C, comincia con «E»),
  vince (dopo «Ha vinto la X:»), cosa (cosa fa, al giovedì), domanda (domanda ai follower, giovedì),
  regalo (dopo «È venerdì:»), righe (due righe del venerdì), manda («Mandatela a chi…»), descrizione (per il banco),
  periodo (["MM-GG", "MM-GG"]: dal giorno al giorno dell'anno in cui va bene, facoltativo), app (configurazione per automatico/regali.py).
"""
import json, os

QUI = os.path.dirname(os.path.abspath(__file__))
P = "Gratis, senza registrazione e senza pubblicità. Tutto resta solo sul tuo telefono e funziona anche senza internet."

def idea(id, nome, emoji, telefono, problema, storia, domandaE, vince, cosa, domanda, regalo, righe, manda, descrizione, tipo, slogan, opzioni, periodo=None, breve=None):
    d = dict(id=id, nome=nome, emoji=emoji, telefono=telefono, problema=problema, storia=storia, domandaE=domandaE, vince=vince, cosa=cosa,
             domanda=domanda, regalo=regalo, righe=righe, manda=manda, descrizione=descrizione,
             app=dict(nome=nome, breve=breve or telefono, emoji=emoji, tipo=tipo, slogan=slogan, descrizione=descrizione, chiave=id + "-v1", opzioni=opzioni, piede=P))
    if periodo: d["periodo"] = periodo
    return d

