def main():
    ids = [i["id"] for i in IDEE]; assert len(ids) == len(set(ids))
    for i in IDEE:
        assert i["domandaE"].startswith("E "), i["id"]
        for k in ("storia", "domandaE", "cosa", "domanda", "manda"): assert len(i[k]) <= 90, (i["id"], k)
    json.dump({"nota": "Idee pronte per le prossime settimane: le usa automatico/settimana.py (vedi crea_catalogo.py per lo schema).", "idee": IDEE},
              open(os.path.join(QUI, "catalogo.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print(len(IDEE), "idee")

if __name__ == "__main__":
    main()
